     3	public sealed class CashMachine(IMoneyDispenser dispenser) : ICashMachine
     4	{
     5	    public const int DailyLimit = 200;
     6	    public const int FeeThreshold = 100;
     7	    public const int WithdrawalFee = 5;
     8	    public const int MaxNotesPerPass = 4;
     9	    public const int CassetteCapacity = 5;
    10	
    11	    public AtmResult Execute(AccountState account, Operation operation) => operation switch
    12	    {
    13	        Operation.Withdraw withdraw => Withdraw(account, withdraw.Amount),
    14	        Operation.Deposit deposit => Deposit(account, deposit.Notes),
    15	        _ => throw new ArgumentOutOfRangeException(nameof(operation)),
    16	    };
    17	
    18	    private AtmResult Withdraw(AccountState account, int amount)
    19	    {
    20	        if (amount <= 0 || amount % 10 != 0)
    21	        {
    22	            return Refuse(AtmStatus.InvalidAmount, account);
    23	        }
    24	
    25	        if (account.WithdrawnToday + amount > DailyLimit)
    26	        {
    27	            return Refuse(AtmStatus.DailyLimitExceeded, account);
    28	        }
    29	
    30	        var fee = amount > FeeThreshold ? WithdrawalFee : 0;
    31	        if (amount + fee > account.Balance)
    32	        {
    33	            return Refuse(AtmStatus.InsufficientFunds, account);
    34	        }
    35	
    36	        if (FewestNotes(amount, Available()) is not { } combination)
    37	        {
    38	            return Refuse(AtmStatus.CannotDispense, account);
    39	        }
    40	
    41	        var dispensed = NoteCounts.None;
    42	        foreach (var pass in SplitIntoPasses(combination))
    43	        {
    44	            if (!dispenser.Dispense(pass))
    45	            {
    46	                return new AtmResult(AtmStatus.DispenserFault, dispensed, 0, account);
    47	            }
    48	
    49	            dispensed += pass;
    50	        }
    51	
    52	        var after = new AccountState(account.Balance - amount - fee, account.WithdrawnToday + amount);
    53	
    54	        return new AtmResult(AtmStatus.Ok, combination, fee, after);
    55	    }
    56	
    57	    private AtmResult Deposit(AccountState account, NoteCounts notes)
    58	    {
    59	        if (notes.Fifties < 0 || notes.Twenties < 0 || notes.Tens < 0 || notes.Total <= 0)
    60	        {
    61	            return Refuse(AtmStatus.InvalidAmount, account);
    62	        }
    63	
    64	        if (dispenser.Jammed is { } jammed && notes.Of(jammed) > 0)
    65	        {
    66	            return Refuse(AtmStatus.CassetteJammed, account);
    67	        }
    68	
    69	        var after = dispenser.Stock + notes;
    70	        if (after.Fifties > CassetteCapacity || after.Twenties > CassetteCapacity || after.Tens > CassetteCapacity)
    71	        {
    72	            return Refuse(AtmStatus.CassetteFull, account);
    73	        }
    74	
    75	        if (!dispenser.Load(notes))
    76	        {
    77	            return new AtmResult(AtmStatus.DispenserFault, NoteCounts.None, 0, account);
    78	        }
    79	
    80	        return new AtmResult(AtmStatus.Ok, NoteCounts.None, 0, account with { Balance = account.Balance + notes.Value });
    81	    }
    82	
    83	    private static AtmResult Refuse(AtmStatus status, AccountState account) =>
    84	        new(status, NoteCounts.None, 0, account);
    85	
    86	    /// <summary>Le stock utilisable : la cassette bloquée compte pour zéro, un compte négatif aussi.</summary>
    87	    private NoteCounts Available()
    88	    {
    89	        var stock = dispenser.Stock;
    90	        var jammed = dispenser.Jammed;
    91	
    92	        return new NoteCounts(
    93	            jammed == Denomination.Fifty ? 0 : Math.Max(0, stock.Fifties),
    94	            jammed == Denomination.Twenty ? 0 : Math.Max(0, stock.Twenties),
    95	            jammed == Denomination.Ten ? 0 : Math.Max(0, stock.Tens));
    96	    }
    97	
    98	    /// <summary>La combinaison exacte qui compte le moins de billets, ou <c>null</c>.</summary>
    99	    private static NoteCounts? FewestNotes(int amount, NoteCounts available)
   100	    {
   101	        NoteCounts? best = null;
   102	        for (var fifties = Math.Min(available.Fifties, amount / 50); fifties >= 0; fifties--)
   103	        {
   104	            var afterFifties = amount - fifties * 50;
   105	            for (var twenties = Math.Min(available.Twenties, afterFifties / 20); twenties >= 0; twenties--)
   106	            {
   107	                var rest = afterFifties - twenties * 20;
   108	                if (rest % 10 != 0 || rest / 10 > available.Tens)
   109	                {
   110	                    continue;
   111	                }
   112	
   113	                var candidate = new NoteCounts(fifties, twenties, rest / 10);
   114	                if (best is null || candidate.Total < best.Value.Total)
   115	                {
   116	                    best = candidate;
   117	                }
   118	            }
   119	        }
   120	
   121	        return best;
   122	    }
   123	
   124	    /// <summary>Découpe la combinaison en passages d'au plus 4 billets.</summary>
   125	    private static IEnumerable<NoteCounts> SplitIntoPasses(NoteCounts notes)
   126	    {
   127	        var remaining = notes;
   128	        while (remaining.Total > 0)
   129	        {
   130	            var room = MaxNotesPerPass;
   131	            var fifties = Math.Min(room, remaining.Fifties);
   132	            room -= fifties;
   133	            var twenties = Math.Min(room, remaining.Twenties);
   134	            room -= twenties;
   135	            var tens = Math.Min(room, remaining.Tens);
   136	
   137	            var pass = new NoteCounts(fifties, twenties, tens);
   138	            remaining -= pass;
   139	
   140	            yield return pass;
   141	        }
   142	    }
   143	}
namespace Atm;

public enum Denomination { Fifty = 50, Twenty = 20, Ten = 10 }

public enum AtmStatus
{
    Ok,
    InvalidAmount,
    DailyLimitExceeded,
    InsufficientFunds,
    CannotDispense,
    CassetteJammed,
    CassetteFull,
    DispenserFault,
}

public readonly record struct NoteCounts(int Fifties, int Twenties, int Tens)
{
    public static NoteCounts None => default;
    public int Total => Fifties + Twenties + Tens;
    public int Value => Fifties * 50 + Twenties * 20 + Tens * 10;

    public int Of(Denomination denomination) => denomination switch
    {
        Denomination.Fifty => Fifties,
        Denomination.Twenty => Twenties,
        _ => Tens,
    };

    public static NoteCounts operator +(NoteCounts a, NoteCounts b) =>
        new(a.Fifties + b.Fifties, a.Twenties + b.Twenties, a.Tens + b.Tens);

    public static NoteCounts operator -(NoteCounts a, NoteCounts b) =>
        new(a.Fifties - b.Fifties, a.Twenties - b.Twenties, a.Tens - b.Tens);
}

public readonly record struct AccountState(int Balance, int WithdrawnToday);

public abstract record Operation
{
    public sealed record Withdraw(int Amount) : Operation;

    public sealed record Deposit(NoteCounts Notes) : Operation;
}

public readonly record struct AtmResult(AtmStatus Status, NoteCounts Notes, int Fee, AccountState Account);

public interface IMoneyDispenser
{
    NoteCounts Stock { get; }

    Denomination? Jammed { get; }

    bool Dispense(NoteCounts notes);

    bool Load(NoteCounts notes);
}

public interface ICashMachine
{
    AtmResult Execute(AccountState account, Operation operation);
}
namespace Atm;

/// <summary>Le vrai module de billets, déterministe.</summary>
public sealed class MoneyDispenser(NoteCounts stock, Denomination? jammed = null) : IMoneyDispenser
{
    public const int MaxNotesPerPass = 4;
    public const int CassetteCapacity = 5;

    public NoteCounts Stock { get; private set; } = stock;

    public Denomination? Jammed { get; } = jammed;

    public bool Dispense(NoteCounts notes)
    {
        var enough = notes.Fifties <= Stock.Fifties && notes.Twenties <= Stock.Twenties && notes.Tens <= Stock.Tens;
        if (!IsValid(notes) || notes.Total > MaxNotesPerPass || !enough)
        {
            return false;
        }

        Stock -= notes;

        return true;
    }

    public bool Load(NoteCounts notes)
    {
        var after = Stock + notes;
        var fits = after.Fifties <= CassetteCapacity && after.Twenties <= CassetteCapacity && after.Tens <= CassetteCapacity;
        if (!IsValid(notes) || !fits)
        {
            return false;
        }

        Stock = after;

        return true;
    }

    private bool IsValid(NoteCounts notes) =>
        notes is { Fifties: >= 0, Twenties: >= 0, Tens: >= 0, Total: > 0 }
        && (Jammed is not { } cassette || notes.Of(cassette) == 0);
}
